#!/usr/bin/env bash
# =============================================================================
# bootstrap_migration_toolkit.sh
# Self-extracting toolkit seeder. Paste the ENTIRE contents of this file into a
# Databricks web terminal (or run it locally) to recreate the ./migration/
# toolkit folder in the current directory. Then edit migration/config.env and
# migration/folders.tsv and run the phase scripts.
# =============================================================================
set -euo pipefail
OUT_DIR="${1:-.}"
mkdir -p "$OUT_DIR"
echo "Extracting migration toolkit into: $OUT_DIR"
base64 -d > "$OUT_DIR/.migration_toolkit.tar.gz" <<'B64EOF'

B64EOF
tar -xzf "$OUT_DIR/.migration_toolkit.tar.gz" -C "$OUT_DIR"
rm -f "$OUT_DIR/.migration_toolkit.tar.gz"
chmod +x "$OUT_DIR"/migration/bin/*.sh 2>/dev/null || true
echo "Done. Toolkit is at $OUT_DIR/migration"
echo "Next: edit migration/config.env and migration/folders.tsv, then run the phase scripts."
